sql.where:
o.user_id = #{userId}
and o.use_time is not null

    and date_format(o.use_time, '%Y-%m') = #{dto.month}

o.use_time is not null

    and g.city = #{dto.city}


    and e.type = #{dto.type}


    and o.verify_type = #{dto.verifyType}


    and (o.order_no like concat('%', #{dto.keyword}, '%')
         or e.title like concat('%', #{dto.keyword}, '%')
         or o.contact_name like concat('%', #{dto.keyword}, '%'))


    and o.use_time >= #{dto.startDate}


    and o.use_time < date_add(#{dto.endDate}, interval 1 day)

mapper.select:
select o.id, o.use_time, o.order_no, o.contact_name, o.quantity, o.verify_type, e.title as exhibition_title, a.name as verify_admin_name from exhibition_order o join exhibition e on e.id = o.exhibition_id join gallery g on g.id = o.gallery_id
left join admin a on a.id = o.verify_admin_id
order by o.use_time desc, o.id desc limit #{dto.offset}, #{dto.limit}
